const MAN_ICON = { om: 'om', shanti: 'lotus', ganesha: 'ganesha', om108: 'mala', lam: 'lam', vam: 'vam', ram: 'ram', yam: 'yam', ham: 'ham', ajna: 'ajna', satnamwahe: 'eye', omnamo: 'hands', ramadasa8: 'sunmoon', ganputi: 'infinity', rama: 'sunmoon', gurubrahma: 'flame', lovepeace: 'heart', lumen: 'light', triple: 'shield', japman: 'wave', satnarayan: 'sun', gaitri: 'star', eckonkar: 'wave', harharhari: 'wave', wahnabel: 'wave', wahejio: 'wave', guruRamDas: 'wave', guruRam: 'wave', mul: 'wave', hargobinde: 'wave', lichtgebet: 'light', kabbalah: 'cross', metta: 'heart', adi: 'hands', mangala: 'shield', lokah: 'heart', asato: 'light', gayatri: 'sun', mahamrit: 'eye', sahanav: 'wave', omnamahshivaya: 'trident', ommani: 'lotus' };
const manById = id => MANTRAS.find(m => m.id === id) || null;
function manIconSVG(id) {
  const g = MANICONS[MAN_ICON[id] || 'wave'];
  return `<svg class="fig" viewBox="0 0 100 100" aria-hidden="true"><g fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round">${g}</g></svg>`;
}

// ---------- Oberfläche (Seite Mantras) ----------
const manDefault = () => ({ q: '', t: '', k: '', m: '', open: new Set(), intro: false });
function manFiltered() {
  const f = ui.man, q = norm(f.q || '');
  return MANTRAS.filter(x => (!f.t || x.typ === f.t) && (!f.k || x.kat.includes(f.k)) && (!f.m || x.m === f.m)
    && (!q || norm([x.n, (x.text || []).join(' '), (x.bed || []).map(b => b[0] + ' ' + b[1]).join(' '), (x.wi || []).join(' '), x.fuer || '', x.an || '', x.cd || ''].join(' ')).includes(q)));
}
function manCard(x) {
  const open = ui.man.open.has(x.id);
  const chips = `<span class="chip mt-${x.typ.replace(/[^A-Za-z]/g, '')}">${esc(MAN_TYP[x.typ])}</span>${x.kat.map(k => `<span class="chip kc">${esc(MAN_KAT[k])}</span>`).join('')}`;
  const bed = x.bed ? `<table class="mbed">${x.bed.map(b => `<tr><td class="ml">${esc(b[0])}</td><td>${esc(b[1])}</td></tr>`).join('')}</table>` : '';
  const sec = (t, h) => h ? `<div class="msec"><h5>${t}</h5>${h}</div>` : '';
  const detail = open ? `<div class="mdet">${sec('Bedeutung', bed)}${sec('Wirkung & Beschreibung', (x.wi || []).map(p => `<p>${esc(p)}</p>`).join(''))}${sec('Anleitung', x.an ? `<p>${esc(x.an)}</p>` : '')}${sec('Lied / CD', x.cd ? `<p>${esc(x.cd)}</p>` : '')}${sec('Mudra', x.mu ? `<p>${esc(x.mu)}</p>` : '')}${(x.mehr || []).map(m => sec(esc(m[0]), `<p>${esc(m[1])}</p>`)).join('')}<p class="muted msrc">Quelle: ${esc(x.q)}</p></div>` : '';
  return `<div class="mcard${open ? ' open' : ''}" id="man-${x.id}"><div class="mhead" data-a="manTog" data-id="${x.id}"><div class="mleft"><div class="xtile cat-mantra_t" title="${esc(x.n)}">${manIconSVG(x.id)}</div></div><div class="mtext">${x.dev ? `<div class="mdev">${esc(x.dev)}</div>` : ''}${x.text.map(l => `<div>${esc(l)}</div>`).join('')}</div>
<div class="minfo"><h4>${esc(x.n)}</h4><div class="mfuer">${esc(x.fuer || '')}</div><div class="mchips">${chips}</div>${open ? '' : `<p class="msum">${esc(((x.wi || [''])[0]).slice(0, 190))}${((x.wi || [''])[0]).length > 190 ? ' …' : ''}</p>`}<span class="mtogl">${open ? '▾ weniger' : '▸ Details'} · ${esc(x.m)}</span></div></div>${detail}</div>`;
}
function viewMantras() {
  ui.man = ui.man || manDefault(); const f = ui.man, list = manFiltered();
  const mods = [...new Set(MANTRAS.map(x => x.m))].sort();
  const intro = f.intro ? `<div class="panel minfop"><h3>Grundlagen aus dem Skript</h3>${MANTRA_INTRO.map(s => `<div class="msec"><h5>${esc(s[0])}</h5><p>${esc(s[1])}</p><p class="muted msrc">Quelle: ${esc(s[2])}</p></div>`).join('')}</div>` : '';
  return `<div class="hero">${LOTUS}<div><h1>Mantras</h1><p>${MANTRAS.length} Mantras, Gebete und Formeln – ausschließlich aus den Lehrgangsskripten.</p></div><span class="grow"></span><button class="ghost" data-a="manIntro">${f.intro ? 'Grundlagen ausblenden' : 'ⓘ Grundlagen: Was ist ein Mantra?'}</button></div>
${intro}<div class="panel mfilt"><div class="grid">${fld('Suche', inp('u:man.q', 'search', f.q, 'placeholder="Name, Text, Bedeutung …" data-live="1"'))}
${fld('Art', sel('u:man.t', [['', 'Alle']].concat(Object.keys(MAN_TYP).map(k => [k, MAN_TYP[k]])), f.t))}
${fld('Anlass / Wirkung', sel('u:man.k', [['', 'Alle']].concat(Object.keys(MAN_KAT).map(k => [k, MAN_KAT[k]])), f.k))}
${fld('Modul', sel('u:man.m', [['', 'Alle']].concat(mods.map(m => [m, m])), f.m))}</div>
<div class="bar"><span class="muted">${list.length} von ${MANTRAS.length} angezeigt</span><span class="grow"></span><button class="ghost sm" data-a="manAll" data-v="1">alle aufklappen</button><button class="ghost sm" data-a="manAll" data-v="0">alle zuklappen</button><button class="ghost sm" data-a="manReset">Filter zurücksetzen</button></div></div>
${list.length ? list.map(manCard).join('') : '<p class="muted">Keine Treffer.</p>'}`;
}
const MANTRA_ACTIONS = {
  pkman(d, el) { openMantraPicker(el, d); },
  pkmanpick(d) {
    const p = ui.pk; if (!p || p.kind !== 'man') return; const { c, s } = sessionOf(p.sid); closePicker();
    s.mantra = { id: d.id }; regenIfNotEdited(c, s, 'mantra'); save(); render();
  },
  manTog(d) { const o = ui.man.open; o.has(d.id) ? o.delete(d.id) : o.add(d.id); render(); },
  manAll(d) { ui.man.open = d.v === '1' ? new Set(manFiltered().map(x => x.id)) : new Set(); render(); },
  manReset() { const o = ui.man.open, i = ui.man.intro; ui.man = manDefault(); ui.man.open = o; ui.man.intro = i; render(); },
  manIntro() { ui.man.intro = !ui.man.intro; render(); }
};
